"""Presentation-only weekly Monster hero. No picks, models, or database access."""

MONSTER_HERO_HTML = '\n{% set featured = namespace(monster=none, side=none) %}\n{% if available | default(false) %}\n    {% for ticket in active_tickets | default([]) | sort(attribute=\'id\', reverse=true) %}\n        {% if featured.monster is none\n              and ticket.is_monster | default(false)\n              and ticket.publication_approved | default(false)\n              and ticket.outcome == \'PENDING\'\n              and 10 <= ticket.legs | length <= 30 %}\n            {% set featured.monster = ticket %}\n        {% endif %}\n        {% if featured.side is none\n              and ticket.is_trial | default(false)\n              and not ticket.is_monster | default(false)\n              and ticket.outcome == \'PENDING\'\n              and ticket.legs | length == 2 %}\n            {% set featured.side = ticket %}\n        {% endif %}\n    {% endfor %}\n{% endif %}\n<style>\n.monster-hero {\n    position: relative;\n    overflow: hidden;\n    margin: 0 0 28px;\n    padding: 26px;\n    border: 2px solid #39ff88;\n    border-radius: 22px;\n    background: linear-gradient(145deg, #071c12, #101714 65%, #072516);\n    box-shadow: 0 0 24px #39ff8833, inset 0 0 28px #39ff8810;\n    color: #e8fff0;\n}\n.monster-hero * { box-sizing: border-box; }\n.monster-eyebrow {\n    margin: 0 0 8px;\n    color: #71ffa8;\n    font-size: 12px;\n    letter-spacing: .18em;\n    text-transform: uppercase;\n}\n.monster-hero h2 {\n    margin: 0;\n    color: #71ffa8;\n    font-size: clamp(26px, 5vw, 42px);\n    text-shadow: 0 0 16px #39ff8855;\n}\n.monster-intro {\n    margin: 10px 0 22px;\n    color: #bfd8c9;\n    line-height: 1.6;\n}\n.monster-machine {\n    display: grid;\n    grid-template-columns: 1fr 150px 1fr;\n    gap: 14px;\n    padding: 16px;\n    border: 1px solid #39ff8844;\n    border-radius: 16px;\n    background: #030b07;\n}\n.monster-reel {\n    display: flex;\n    min-height: 150px;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    padding: 14px;\n    border: 1px solid #39ff8833;\n    border-radius: 12px;\n    background: linear-gradient(#0b2115, #07110b);\n    text-align: center;\n}\n.monster-reel-label {\n    color: #a2bfae;\n    font-size: 11px;\n    letter-spacing: .12em;\n    text-transform: uppercase;\n}\n.monster-reel-value {\n    margin: 10px 0;\n    color: #71ffa8;\n    font-size: 22px;\n    font-weight: 700;\n}\n.monster-reel-note { color: #a2bfae; font-size: 12px; }\n.monster-face {\n    position: relative;\n    width: 100px;\n    height: 100px;\n    border: 3px solid #71ffa8;\n    border-radius: 50%;\n    background: #102a1b;\n    box-shadow: 0 0 22px #39ff8855;\n    animation: monster-spin 8s linear infinite;\n}\n.monster-eyes {\n    position: absolute;\n    top: 17px;\n    left: 0;\n    right: 0;\n    color: #71ffa8;\n    font-size: 29px;\n    font-weight: 800;\n    letter-spacing: 9px;\n    padding-left: 9px;\n}\n.monster-smile {\n    position: absolute;\n    bottom: 19px;\n    left: 25px;\n    width: 44px;\n    height: 23px;\n    border-bottom: 4px solid #71ffa8;\n    border-radius: 0 0 40px 40px;\n}\n.monster-status {\n    margin: 20px 0 8px;\n    color: #e8fff0;\n    font-size: 17px;\n    font-weight: 700;\n}\n.monster-disclaimer {\n    margin: 0;\n    color: #a2bfae;\n    font-size: 13px;\n    line-height: 1.6;\n}\n@keyframes monster-spin {\n    from { transform: rotate(0deg); }\n    to { transform: rotate(360deg); }\n}\n@media (max-width: 600px) {\n    .monster-hero { padding: 18px; }\n    .monster-machine { grid-template-columns: 1fr; }\n    .monster-reel { min-height: 110px; }\n    .monster-center { grid-row: 1; min-height: 145px; }\n}\n@media (prefers-reduced-motion: reduce) {\n    .monster-face { animation: none; }\n}\n\n.monster-layout { display:grid; grid-template-columns: minmax(0,3fr) minmax(230px,1fr); gap:20px; }\n.monster-main { min-width:0; text-align:center; }\n.monster-orbit { position:relative; width:280px; height:280px; margin:20px auto; }\n.monster-orbit .monster-face { position:absolute; inset:0; width:100%; height:100%; }\n.monster-orbit.has-ticket .monster-eyes,\n.monster-orbit.has-ticket .monster-smile { display:none; }\n.monster-orbit:not(.has-ticket) .monster-eyes { top:65px; font-size:65px; }\n.monster-orbit:not(.has-ticket) .monster-smile { left:85px; bottom:60px; width:100px; height:55px; }\n.monster-ticket-center { position:absolute; inset:45px; display:flex; flex-direction:column; justify-content:center; gap:10px; overflow-wrap:anywhere; }\n.monster-ticket-center .monster-reel-value { margin:0; }\n.monster-side { align-self:start; padding:18px; border:1px solid #39ff8855; border-radius:14px; background:#07110b; }\n.monster-side h3 { color:#71ffa8; margin-top:0; }\n.monster-main ul { text-align:left; }\n@media(max-width:700px) {\n    .monster-layout { grid-template-columns:1fr; }\n    .monster-orbit { width:240px; height:240px; }\n    .monster-orbit:not(.has-ticket) .monster-smile { left:65px; }\n}\n</style>\n<section class="monster-hero" aria-labelledby="monster-title">\n    <p class="monster-eyebrow">Weekly showcase</p>\n    <h2 id="monster-title">🎰 Weekly Monster</h2>\n    <p class="monster-intro">The main attraction · 10–30 qualifying legs.</p>\n    <div class="monster-layout">\n        <div class="monster-main" id="monster-main-ticket">\n            <div class="monster-orbit {{ \'has-ticket\' if featured.monster else \'\' }}">\n                <div class="monster-face" aria-hidden="true">\n                    <span class="monster-eyes">&#36;&#36;</span>\n                    <span class="monster-smile"></span>\n                </div>\n                {% if featured.monster %}\n                <div class="monster-ticket-center">\n                    <span class="monster-reel-label">Monster ticket</span>\n                    <span class="monster-reel-value">#{{ featured.monster.id }}</span>\n                    <span>{{ featured.monster.legs | length }} legs</span>\n                    <span class="monster-reel-label">Estimated return</span>\n                    <span class="monster-reel-value">{{ featured.monster.payout }}</span>\n                </div>\n                {% endif %}\n            </div>\n            {% if featured.monster %}\n            <p class="monster-status">Monster · Pending</p>\n            <p>{{ featured.monster.odds }} · Stake {{ featured.monster.stake }}</p>\n            <ul>{% for leg in featured.monster.legs %}<li>{{ leg }}</li>{% endfor %}</ul>\n            <p class="monster-disclaimer">\n                {{ featured.monster.research_label }}<br>\n                Published {{ featured.monster.created }}.\n                Estimated return is not a settled result.\n            </p>\n            {% else %}\n            <p class="monster-status">Waiting for a qualifying Monster.</p>\n            <span class="monster-reel-value">—</span>\n            <p class="monster-disclaimer">\n                No qualifying Monster ticket is available.\n                The side bet does not replace the main Monster.\n            </p>\n            {% endif %}\n        </div>\n        <aside class="monster-side" id="monster-side-bet">\n            <h3>Featured Side Bet</h3>\n            {% if featured.side %}\n            <p>Ticket #{{ featured.side.id }} · 2 legs · Pending</p>\n            <ul>{% for leg in featured.side.legs %}<li>{{ leg }}</li>{% endfor %}</ul>\n            <p>{{ featured.side.odds }}</p>\n            <p>Simulated stake {{ featured.side.stake }}</p>\n            <p>Estimated simulated return {{ featured.side.payout }}</p>\n            <p class="monster-disclaimer">\n                Trial · Not validated · Simulated returns.<br>\n                Published {{ featured.side.created }}.\n            </p>\n            {% else %}\n            <p class="monster-disclaimer">No pending two-leg side bet available.</p>\n            {% endif %}\n        </aside>\n    </div>\n</section>\n'


def add_monster_hero(template):
    """Insert once at the top of the dashboard's main content."""
    if 'id="monster-title"' in template:
        return template
    if template.count("<main>") != 1:
        raise ValueError("Expected exactly one dashboard main element")
    return template.replace("<main>", "<main>" + MONSTER_HERO_HTML + RESEARCH_STATUS_HTML + RESEARCH_ELIGIBILITY_HTML, 1)


RESEARCH_STATUS_HTML = '\n{% if available | default(false) %}\n{% set status = research | default({}, true) %}\n<section class="research-status" id="research-status-panel"\n         aria-labelledby="research-status-title">\n    <h2 id="research-status-title">Research status</h2>\n    <p>Automatic parlays: PAUSED · Model approval: NOT APPROVED</p>\n    <p class="muted">\n        Experimental training status is not recorded in the dashboard database.\n        These diagnostics do not grant research qualification or publication approval.\n    </p>\n    {% if status.available | default(false) %}\n    <dl>\n        {% for key, label in [\n            (\'observation_count\', \'Total observations\'),\n            (\'distinct_events\', \'Distinct observed events\'),\n            (\'eligible_settled_events\', \'Eligible settled events\'),\n            (\'recent_audit_events\', \'Recent audit rows\'),\n            (\'invalid_audit_rows\', \'Invalid audit rows\')\n        ] %}\n        <dt>{{ label }}</dt>\n        <dd>{{ status[key] if status[key] is defined\n               and status[key] is not none else \'Unavailable\' }}</dd>\n        {% endfor %}\n        <dt>Last recent audit</dt>\n        <dd>{{ status.last_audit_utc | default(\'Unavailable\', true) }}</dd>\n    </dl>\n    <p class="muted">\n        Eligible settled events passed the evaluator checks; this count does not\n        establish training readiness or model reliability.\n        Recent audits cover the last two hours and count rows, not unique events.\n    </p>\n    {% if status.recent_audit_events | default(none) == 0 %}\n    <p>No recent audit data; generation remains paused.</p>\n    {% elif status.blockers | default([]) %}\n    <h3>Recorded blockers</h3>\n    <ul>\n        {% for blocker in status.blockers %}\n        <li>{{ blocker.label }} · {{ blocker.count }} audit row(s)</li>\n        {% endfor %}\n    </ul>\n    {% else %}\n    <p>No blockers recorded in the available recent audits;\n       this does not establish readiness. Generation remains paused.</p>\n    {% endif %}\n    {% else %}\n    <p>Research diagnostics are unavailable; counts are unknown.\n       Generation remains paused.</p>\n    {% endif %}\n</section>\n{% endif %}\n'


RESEARCH_ELIGIBILITY_HTML = '\n{% if available | default(false) %}\n{% set status = research | default({}, true) %}\n<section class="research-status" id="research-eligibility-panel"\n         aria-labelledby="research-eligibility-title">\n    <h2 id="research-eligibility-title">Settled-event eligibility diagnostics</h2>\n    {% if status.available | default(false) %}\n    <dl>\n        <dt>Events selected before integrity checks</dt>\n        <dd>{{ status.events_selected_before_integrity_checks\n               if status.events_selected_before_integrity_checks is defined\n               and status.events_selected_before_integrity_checks is not none\n               else \'Unavailable\' }}</dd>\n        <dt>Superseded eligible observations</dt>\n        <dd>{{ status.superseded_eligible_observations\n               if status.superseded_eligible_observations is defined\n               and status.superseded_eligible_observations is not none\n               else \'Unavailable\' }}</dd>\n    </dl>\n    <p class="muted">\n        Superseded observations were replaced by another eligible observation\n        for the same event; they are not integrity failures.\n    </p>\n    {% for key, title, unit in [\n        (\'excluded_observations_by_reason\',\n         \'Excluded observations before event selection\', \'observation(s)\'),\n        (\'excluded_selected_events_by_reason\',\n         \'Rejected selected events after integrity checks\', \'event(s)\')\n    ] %}\n    <h3>{{ title }}</h3>\n    {% set reasons = status[key] | default(none) %}\n    {% if reasons is none %}\n    <p>Diagnostics unavailable.</p>\n    {% elif reasons %}\n    <ul>\n        {% for reason, count in reasons | dictsort %}\n        <li>{{ reason }} · {{ count }} {{ unit }}</li>\n        {% endfor %}\n    </ul>\n    {% else %}\n    <p>No exclusions recorded at this stage.</p>\n    {% endif %}\n    {% endfor %}\n    {% else %}\n    <p>Eligibility diagnostics are unavailable; counts are unknown.</p>\n    {% endif %}\n    <p class="muted">\n        Observation counts and event counts are different units.\n        These diagnostics do not establish model readiness or approval.\n        Automatic generation remains paused.\n    </p>\n</section>\n{% endif %}\n'
